: null, "parcelas_plano": 12, "plano_centavos": 514800, "total_centavos": 514800, "parcelas_servicos": null, "servicos_centavos": 0, "modalidade_cobranca": "anual", "corrida_periodo_meses": null, "corrida_total_centavos": null},"aceite_id":"d722a603-2d77-4d7d-9b95-650d426f84e1","teste_admin":true,"criado_por":"a95eaac6-da86-45a2-a877-0e10316d6e64","pago_em":null,"pagamento_tipo":null,"pagamento_ref":null,"consentimento_contato_em":"2026-10-13T23:21:20.722009+00:00","notificacao_pagamento_id":null,"email_confirmacao_reservado_em":null,"email_confirmacao_enviado_em":null,"email_confirmacao_erro":null,"notificacao_cartao_combinar_id":null,"pagamento_parcelas":null,"pagamento_nsu":null,"pagamento_tid_mascarado":null,"notificacao_cartao_recusado_id":null,"notificacao_cartao_divergente_id":null,"assinatura_cancelada_em":null,"assinatura_cancelada_por":null,"aluno_ativado_id":null,"venda_id":null,"contrato_id":null,"ativada_em":null,"ativacao_vinculo":null,"ativacao_erro":null,"ativacao_erro_em":null,"notificacao_ativacao_id":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"f293069a-c074-4a20-83e6-d69a10c4c2b1","proposta_id":"6a2d465e-16e8-4792-8dfa-8ce361ef4200","template_id":"ebeb495b-77cf-4a7a-9a4c-7b45fbbcdcfb","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: NICOLAS TESTE (teste 2B), Data de nascimento: 02/05/1990, CPF: 568.653.549-31, RG: , Endereço: Av. Independência, 100, Independência, Porto Alegre/RS – CEP 90035-000, E-mail: nicolas_ja@hotmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor: R$ 5.148,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 13/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90035-000", "CPF": "***.***.**931", "DIA": "13", "MES": "10", "NOME": "NICOLAS TESTE (teste 2B)", "EMAIL": "nicolas_ja@hotmail.com", "BAIRRO": "Independência", "CIDADE": "Porto Alegre", "ENDERECO": "Av. Independência, 100", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 5.148,00", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "02/05/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 5.148,00"},"hash_texto":"bc3ff23beddae615595517d80bc46495260b4390f8caaa5e6deb2bb150af329e","valor_total_centavos":514800,"ip":"35.195.106.39","user_agent":"teste-2B","origem":"site","aceito_em":"2026-10-13T13:59:59.34117+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-13T13:59:59.34117+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"512af293-0218-48ab-8d75-bff93d6bfc22","proposta_id":"19bf056f-8b42-4e62-a5f2-35baf343d90b","template_id":"ebeb495b-77cf-4a7a-9a4c-7b45fbbcdcfb","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: NICOLAS TESTE (teste 2C), Data de nascimento: 02/05/1990, CPF: 568.653.549-31, RG: , Endereço: Av. Independência, 100, Independência, Porto Alegre/RS – CEP 90035-000, E-mail: nicolas_ja@hotmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor: R$ 5.148,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 13/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90035-000", "CPF": "***.***.**931", "DIA": "13", "MES": "10", "NOME": "NICOLAS TESTE (teste 2C)", "EMAIL": "nicolas_ja@hotmail.com", "BAIRRO": "Independência", "CIDADE": "Porto Alegre", "ENDERECO": "Av. Independência, 100", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 5.148,00", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "02/05/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 5.148,00"},"hash_texto":"af5166d74fc443bfdd059685c77e25085f07837d5716ee913d7e2b9378ec044e","valor_total_centavos":514800,"ip":"35.195.106.39","user_agent":"Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/141.0.7390.37 Safari/537.36","origem":"site","aceito_em":"2026-10-13T14:11:03.132616+00:00","invalidado_em":"2026-10-13T14:11:25.328562+00:00","motivo_invalidacao":"escolhas alteradas","created_at":"2026-10-13T14:11:03.132616+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"c44d1549-db0f-4459-af32-ae44d1b5a9f7","proposta_id":"08f21c0a-4b48-4c65-8a84-191daf596d8f","template_id":"225c44c2-2da6-4f93-aa63-87c4f812908d","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: TESTE 2D1 ADMIN, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Av. Teste, 1, Centro, Porto Alegre/RS – CEP 90035-000, E-mail: teste2d1@exemplo.invalid, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor mensal: R$ 453,90 (já incluída a taxa de recorrência de R$ 24,90)<br>\\nVigência: 12 (doze) meses, com fidelidade mínima de 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano possui condição comercial especial em razão da fidelidade contratual mínima de 12 (doze) meses, sendo realizado por meio de cobrança recorrente mensal automática por cartão de crédito ou PIX Automático, conforme a forma de pagamento cadastrada pelo ALUNO, não se caracterizando como contratação mensal independente, mas como forma de pagamento parcelada do período contratual total.</p>\\n<p>§2º O valor mensal inclui a taxa de recorrência de R$ 24,90, que não é restituível em nenhuma hipótese.</p>\\n<p>§3º É responsabilidade do ALUNO manter atualizada a forma de pagamento cadastrada.</p>\\n<p>§4º Em caso de falha na cobrança ou inadimplência, o acesso do ALUNO poderá ser suspenso até regularização do pagamento.</p>\\n<p>§5º Em caso de atraso no pagamento incidirá multa de 2%, juros de 1% ao mês e correção monetária.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares são pagos à parte, em até 6 (seis) parcelas no cartão de crédito ou por PIX à vista, independentemente da cobrança mensal do plano.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o plano contratado possui fidelidade mínima de 12 (doze) meses, com cobrança realizada de forma recorrente mensal por cartão de crédito ou PIX Automático, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>• até o 4º mês de contrato: multa de 25% sobre o valor das mensalidades vincendas<br>\\n• entre o 5º e 6º mês: multa de 20% sobre o valor das mensalidades vincendas<br>\\n• entre o 7º e 12º mês: multa de 15% sobre o valor das mensalidades vincendas</p>\\n<p>§2º Após a solicitação formal de cancelamento, as cobranças recorrentes futuras serão interrompidas, permanecendo devido pelo ALUNO apenas:<br>\\nI – os valores já vencidos até a data do cancelamento;<br>\\nII – o valor correspondente à multa prevista nesta cláusula.</p>\\n<p>§3º O valor da multa poderá ser cobrado:<br>\\nI – em parcela única; ou<br>\\nII – de forma parcelada, a critério da CONTRATADA.</p>\\n<p>§4º Nos pagamentos realizados em modalidade recorrente, não haverá estorno de valores já cobrados, considerando que os serviços foram disponibilizados de forma proporcional ao período de utilização.</p>\\n<p>§5º Os serviços complementares seguem a cláusula 4ª-A: são cobrados à parte, não integram o cálculo da multa deste plano e seus créditos não são afetados pelo cancelamento.</p>\\n<p>§6º A taxa de recorrência incluída nas mensalidades não é restituível.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, ainda que a cobrança seja mensal, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 13/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90035-000", "CPF": "***.***.**725", "DIA": "13", "MES": "10", "NOME": "TESTE 2D1 ADMIN", "EMAIL": "teste2d1@exemplo.invalid", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Av. Teste, 1", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 453,90", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 24,90", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 5.446,80"},"hash_texto":"2bc4620565ffc7fefefa6331ee2a71237702c05fa81d47c695e7d6708c724fd3","valor_total_centavos":544680,"ip":"35.195.106.39","user_agent":"python-requests/2.32.5","origem":"site","aceito_em":"2026-10-13T14:27:53.131413+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-13T14:27:53.131413+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"fc7c7d11-2d20-428d-b3e9-9f9291da8d38","proposta_id":"c0845789-9dce-402a-98b5-1a0f34ee5099","template_id":"225c44c2-2da6-4f93-aa63-87c4f812908d","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: TESTE 2D1B ADMIN, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Av. Teste, 1, Centro, Porto Alegre/RS – CEP 90035-000, E-mail: teste2d1@exemplo.invalid, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor mensal: R$ 453,90 (já incluída a taxa de recorrência de R$ 24,90)<br>\\nVigência: 12 (doze) meses, com fidelidade mínima de 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano possui condição comercial especial em razão da fidelidade contratual mínima de 12 (doze) meses, sendo realizado por meio de cobrança recorrente mensal automática por cartão de crédito ou PIX Automático, conforme a forma de pagamento cadastrada pelo ALUNO, não se caracterizando como contratação mensal independente, mas como forma de pagamento parcelada do período contratual total.</p>\\n<p>§2º O valor mensal inclui a taxa de recorrência de R$ 24,90, que não é restituível em nenhuma hipótese.</p>\\n<p>§3º É responsabilidade do ALUNO manter atualizada a forma de pagamento cadastrada.</p>\\n<p>§4º Em caso de falha na cobrança ou inadimplência, o acesso do ALUNO poderá ser suspenso até regularização do pagamento.</p>\\n<p>§5º Em caso de atraso no pagamento incidirá multa de 2%, juros de 1% ao mês e correção monetária.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares são pagos à parte, em até 6 (seis) parcelas no cartão de crédito ou por PIX à vista, independentemente da cobrança mensal do plano.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o plano contratado possui fidelidade mínima de 12 (doze) meses, com cobrança realizada de forma recorrente mensal por cartão de crédito ou PIX Automático, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>• até o 4º mês de contrato: multa de 25% sobre o valor das mensalidades vincendas<br>\\n• entre o 5º e 6º mês: multa de 20% sobre o valor das mensalidades vincendas<br>\\n• entre o 7º e 12º mês: multa de 15% sobre o valor das mensalidades vincendas</p>\\n<p>§2º Após a solicitação formal de cancelamento, as cobranças recorrentes futuras serão interrompidas, permanecendo devido pelo ALUNO apenas:<br>\\nI – os valores já vencidos até a data do cancelamento;<br>\\nII – o valor correspondente à multa prevista nesta cláusula.</p>\\n<p>§3º O valor da multa poderá ser cobrado:<br>\\nI – em parcela única; ou<br>\\nII – de forma parcelada, a critério da CONTRATADA.</p>\\n<p>§4º Nos pagamentos realizados em modalidade recorrente, não haverá estorno de valores já cobrados, considerando que os serviços foram disponibilizados de forma proporcional ao período de utilização.</p>\\n<p>§5º Os serviços complementares seguem a cláusula 4ª-A: são cobrados à parte, não integram o cálculo da multa deste plano e seus créditos não são afetados pelo cancelamento.</p>\\n<p>§6º A taxa de recorrência incluída nas mensalidades não é restituível.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, ainda que a cobrança seja mensal, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 13/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90035-000", "CPF": "***.***.**725", "DIA": "13", "MES": "10", "NOME": "TESTE 2D1B ADMIN", "EMAIL": "teste2d1@exemplo.invalid", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Av. Teste, 1", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 453,90", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 24,90", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 5.446,80"},"hash_texto":"ff6766069c4cd02b6634ed918303ee9c9cafe5f146207e81d0fa04a5bee0b60b","valor_total_centavos":544680,"ip":"35.195.106.39","user_agent":"python-requests/2.32.5","origem":"site","aceito_em":"2026-10-13T14:35:12.797998+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-13T14:35:12.797998+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"6aa2982b-8959-4af7-9241-be0a936a0e40","proposta_id":"c016f027-678d-4f4e-a759-1cb1e590778d","template_id":"225c44c2-2da6-4f93-aa63-87c4f812908d","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: TESTE 2D1C ADMIN, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Av. Teste, 1, Centro, Porto Alegre/RS – CEP 90035-000, E-mail: teste2d1@exemplo.invalid, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor mensal: R$ 453,90 (já incluída a taxa de recorrência de R$ 24,90)<br>\\nVigência: 12 (doze) meses, com fidelidade mínima de 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano possui condição comercial especial em razão da fidelidade contratual mínima de 12 (doze) meses, sendo realizado por meio de cobrança recorrente mensal automática por cartão de crédito ou PIX Automático, conforme a forma de pagamento cadastrada pelo ALUNO, não se caracterizando como contratação mensal independente, mas como forma de pagamento parcelada do período contratual total.</p>\\n<p>§2º O valor mensal inclui a taxa de recorrência de R$ 24,90, que não é restituível em nenhuma hipótese.</p>\\n<p>§3º É responsabilidade do ALUNO manter atualizada a forma de pagamento cadastrada.</p>\\n<p>§4º Em caso de falha na cobrança ou inadimplência, o acesso do ALUNO poderá ser suspenso até regularização do pagamento.</p>\\n<p>§5º Em caso de atraso no pagamento incidirá multa de 2%, juros de 1% ao mês e correção monetária.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares são pagos à parte, em até 6 (seis) parcelas no cartão de crédito ou por PIX à vista, independentemente da cobrança mensal do plano.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o plano contratado possui fidelidade mínima de 12 (doze) meses, com cobrança realizada de forma recorrente mensal por cartão de crédito ou PIX Automático, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>• até o 4º mês de contrato: multa de 25% sobre o valor das mensalidades vincendas<br>\\n• entre o 5º e 6º mês: multa de 20% sobre o valor das mensalidades vincendas<br>\\n• entre o 7º e 12º mês: multa de 15% sobre o valor das mensalidades vincendas</p>\\n<p>§2º Após a solicitação formal de cancelamento, as cobranças recorrentes futuras serão interrompidas, permanecendo devido pelo ALUNO apenas:<br>\\nI – os valores já vencidos até a data do cancelamento;<br>\\nII – o valor correspondente à multa prevista nesta cláusula.</p>\\n<p>§3º O valor da multa poderá ser cobrado:<br>\\nI – em parcela única; ou<br>\\nII – de forma parcelada, a critério da CONTRATADA.</p>\\n<p>§4º Nos pagamentos realizados em modalidade recorrente, não haverá estorno de valores já cobrados, considerando que os serviços foram disponibilizados de forma proporcional ao período de utilização.</p>\\n<p>§5º Os serviços complementares seguem a cláusula 4ª-A: são cobrados à parte, não integram o cálculo da multa deste plano e seus créditos não são afetados pelo cancelamento.</p>\\n<p>§6º A taxa de recorrência incluída nas mensalidades não é restituível.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, ainda que a cobrança seja mensal, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 13/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90035-000", "CPF": "***.***.**725", "DIA": "13", "MES": "10", "NOME": "TESTE 2D1C ADMIN", "EMAIL": "teste2d1@exemplo.invalid", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Av. Teste, 1", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 453,90", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 24,90", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 5.446,80"},"hash_texto":"af2333947f03e99ae104903f8f2b8f784ab9e42bf749d058f36cf2326a080164","valor_total_centavos":544680,"ip":"35.195.106.39","user_agent":"python-requests/2.32.5","origem":"site","aceito_em":"2026-10-13T15:00:19.026574+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-13T15:00:19.026574+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"63e263b3-e728-4aa0-9d38-23e3eb01651f","proposta_id":"fd92dd92-6f0b-4e93-b13e-cd1d0e91af12","template_id":"38180919-6f31-462a-8374-08975aa7d379","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: Nicolas Squeff Janovik, Data de nascimento: 02/12/1989, CPF: 015.743.080-41, RG: , Endereço: Avenida Independência, 358, Centro Histórico, Porto Alegre/RS – CEP 90035-070, E-mail: nicolas.janovik@gmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Pro 3x<br>\\nFrequência: 3 (três) vezes por semana<br>\\nValor: R$ 7.188,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>2 avaliações funcionais (1º e 6º mês)</li>\\n<li>20 dias de licença</li>\\n<li>fixação de horários</li>\\n<li>4 sessões por mês de bota de compressão pneumática, agendáveis no portal, não acumuláveis</li>\\n<li>brinde: camiseta e garrafinha</li>\\n<li>condições especiais no Clube Fortem</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA REPOSIÇÃO DE CRÉDITOS</h2>\\n<p><strong>Cláusula 15ª-A</strong> – Ao final da vigência deste contrato, 50% (cinquenta por cento) do saldo de créditos de treino não utilizados, arredondado para cima, será transferido ao novo plano contratado pelo ALUNO, para uso conforme a vigência deste novo plano, desde que o novo plano seja contratado em até 30 (trinta) dias corridos após o término da vigência deste contrato; encerrado esse prazo, o saldo não será transferido.</p>\\n<p>Parágrafo único – A reposição vale somente para créditos de treino, não se aplicando a créditos de nutrição, reabilitação ou avaliações.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 20 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 13/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90035-070", "CPF": "***.***.**041", "DIA": "13", "MES": "10", "NOME": "Nicolas Squeff Janovik", "EMAIL": "nicolas.janovik@gmail.com", "BAIRRO": "Centro Histórico", "CIDADE": "Porto Alegre", "ENDERECO": "Avenida Independência, 358", "FREQUENCIA": "3 (três) vezes por semana", "LICENCA_DIAS": "20", "VALOR_MENSAL": "R$ 7.188,00", "NOME_CONTRATO": "Pro 3x", "DATA_NASCIMENTO": "02/12/1989", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>2 avaliações funcionais (1º e 6º mês)</li>\\n<li>20 dias de licença</li>\\n<li>fixação de horários</li>\\n<li>4 sessões por mês de bota de compressão pneumática, agendáveis no portal, não acumuláveis</li>\\n<li>brinde: camiseta e garrafinha</li>\\n<li>condições especiais no Clube Fortem</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "<h2>DA REPOSIÇÃO DE CRÉDITOS</h2>\\n<p><strong>Cláusula 15ª-A</strong> – Ao final da vigência deste contrato, 50% (cinquenta por cento) do saldo de créditos de treino não utilizados, arredondado para cima, será transferido ao novo plano contratado pelo ALUNO, para uso conforme a vigência deste novo plano, desde que o novo plano seja contratado em até 30 (trinta) dias corridos após o término da vigência deste contrato; encerrado esse prazo, o saldo não será transferido.</p>\\n<p>Parágrafo único – A reposição vale somente para créditos de treino, não se aplicando a créditos de nutrição, reabilitação ou avaliações.</p>\\n\\n", "VALOR_FINAL_CONTRATO": "R$ 7.188,00"},"hash_texto":"c95f2eb55730d897be6a5efb5e9798bf791b9b915a20c1442619333e73876655","valor_total_centavos":718800,"ip":"189.6.233.112","user_agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/154.0.0.0 Safari/537.36","origem":"site","aceito_em":"2026-10-13T15:04:54.803697+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-13T15:04:54.803697+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"fd87a702-d7d7-4812-83e4-78bab187a996","proposta_id":"84a066b6-3644-46b7-a520-baa1c17cda10","template_id":"ebeb495b-77cf-4a7a-9a4c-7b45fbbcdcfb","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: TESTE 2D2 CARTAO_PARCELADO, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Rua de Teste, 1, Centro, Porto Alegre/RS – CEP 90035-000, E-mail: teste2d2@exemplo.invalid, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor: R$ 6.768,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 13/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90035-000", "CPF": "***.***.**725", "DIA": "13", "MES": "10", "NOME": "TESTE 2D2 CARTAO_PARCELADO", "EMAIL": "teste2d2@exemplo.invalid", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Rua de Teste, 1", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 5.148,00", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 6.768,00"},"hash_texto":"c40622effc91ceaaba9b6c58daa0857728959e1c056469f0de6c920e2665ea05","valor_total_centavos":676800,"ip":"35.195.106.39","user_agent":"Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/141.0.7390.37 Safari/537.36","origem":"site","aceito_em":"2026-10-13T15:11:58.560773+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-13T15:11:58.560773+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"960b9e69-693c-49f5-9212-dc52e5942d5c","proposta_id":"7268da33-d2d4-433b-8d72-79e9a6d0f61d","template_id":"ebeb495b-77cf-4a7a-9a4c-7b45fbbcdcfb","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: TESTE 2D2 PIX_VISTA, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Rua de Teste, 1, Centro, Porto Alegre/RS – CEP 90035-000, E-mail: teste2d2@exemplo.invalid, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor: R$ 6.768,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 13/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90035-000", "CPF": "***.***.**725", "DIA": "13", "MES": "10", "NOME": "TESTE 2D2 PIX_VISTA", "EMAIL": "teste2d2@exemplo.invalid", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Rua de Teste, 1", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 5.148,00", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 6.768,00"},"hash_texto":"c2d03eaec6876cfc22bcbc0a0ac642bbb85c8339c0ee5d7db56617cb07ccc7d0","valor_total_centavos":676800,"ip":"35.195.106.39","user_agent":"Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/141.0.7390.37 Safari/537.36","origem":"site","aceito_em":"2026-10-13T15:12:39.283343+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-13T15:12:39.283343+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"6bba06c4-b633-488e-958b-7f4015a5ad54","proposta_id":"85f27e76-e3c0-4d51-8000-a52f9a6d6c14","template_id":"225c44c2-2da6-4f93-aa63-87c4f812908d","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: TESTE 2D2 RECORRENCIA, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Rua de Teste, 1, Centro, Porto Alegre/RS – CEP 90035-000, E-mail: teste2d2@exemplo.invalid, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor mensal: R$ 453,90 (já incluída a taxa de recorrência de R$ 24,90)<br>\\nVigência: 12 (doze) meses, com fidelidade mínima de 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano possui condição comercial especial em razão da fidelidade contratual mínima de 12 (doze) meses, sendo realizado por meio de cobrança recorrente mensal automática por cartão de crédito ou PIX Automático, conforme a forma de pagamento cadastrada pelo ALUNO, não se caracterizando como contratação mensal independente, mas como forma de pagamento parcelada do período contratual total.</p>\\n<p>§2º O valor mensal inclui a taxa de recorrência de R$ 24,90, que não é restituível em nenhuma hipótese.</p>\\n<p>§3º É responsabilidade do ALUNO manter atualizada a forma de pagamento cadastrada.</p>\\n<p>§4º Em caso de falha na cobrança ou inadimplência, o acesso do ALUNO poderá ser suspenso até regularização do pagamento.</p>\\n<p>§5º Em caso de atraso no pagamento incidirá multa de 2%, juros de 1% ao mês e correção monetária.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares são pagos à parte, em até 6 (seis) parcelas no cartão de crédito ou por PIX à vista, independentemente da cobrança mensal do plano.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o plano contratado possui fidelidade mínima de 12 (doze) meses, com cobrança realizada de forma recorrente mensal por cartão de crédito ou PIX Automático, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>• até o 4º mês de contrato: multa de 25% sobre o valor das mensalidades vincendas<br>\\n• entre o 5º e 6º mês: multa de 20% sobre o valor das mensalidades vincendas<br>\\n• entre o 7º e 12º mês: multa de 15% sobre o valor das mensalidades vincendas</p>\\n<p>§2º Após a solicitação formal de cancelamento, as cobranças recorrentes futuras serão interrompidas, permanecendo devido pelo ALUNO apenas:<br>\\nI – os valores já vencidos até a data do cancelamento;<br>\\nII – o valor correspondente à multa prevista nesta cláusula.</p>\\n<p>§3º O valor da multa poderá ser cobrado:<br>\\nI – em parcela única; ou<br>\\nII – de forma parcelada, a critério da CONTRATADA.</p>\\n<p>§4º Nos pagamentos realizados em modalidade recorrente, não haverá estorno de valores já cobrados, considerando que os serviços foram disponibilizados de forma proporcional ao período de utilização.</p>\\n<p>§5º Os serviços complementares seguem a cláusula 4ª-A: são cobrados à parte, não integram o cálculo da multa deste plano e seus créditos não são afetados pelo cancelamento.</p>\\n<p>§6º A taxa de recorrência incluída nas mensalidades não é restituível.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, ainda que a cobrança seja mensal, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 13/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90035-000", "CPF": "***.***.**725", "DIA": "13", "MES": "10", "NOME": "TESTE 2D2 RECORRENCIA", "EMAIL": "teste2d2@exemplo.invalid", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Rua de Teste, 1", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 453,90", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 24,90", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 7.066,80"},"hash_texto":"64ae8a9960b1d3a757a38fb21ea6e63df9fe69fe99563324e816f2c3a655bdea","valor_total_centavos":706680,"ip":"35.195.106.39","user_agent":"Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/141.0.7390.37 Safari/537.36","origem":"site","aceito_em":"2026-10-13T15:12:58.013816+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-13T15:12:58.013816+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"4d8b6319-5523-4e59-b798-715b63fd3ac9","proposta_id":"16989df5-250a-48a4-bbb4-07dfd9216b64","template_id":"225c44c2-2da6-4f93-aa63-87c4f812908d","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: TESTE 2D2 RECORRENCIA, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Rua de Teste, 1, Centro, Porto Alegre/RS – CEP 90035-000, E-mail: teste2d2@exemplo.invalid, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor mensal: R$ 453,90 (já incluída a taxa de recorrência de R$ 24,90)<br>\\nVigência: 12 (doze) meses, com fidelidade mínima de 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano possui condição comercial especial em razão da fidelidade contratual mínima de 12 (doze) meses, sendo realizado por meio de cobrança recorrente mensal automática por cartão de crédito ou PIX Automático, conforme a forma de pagamento cadastrada pelo ALUNO, não se caracterizando como contratação mensal independente, mas como forma de pagamento parcelada do período contratual total.</p>\\n<p>§2º O valor mensal inclui a taxa de recorrência de R$ 24,90, que não é restituível em nenhuma hipótese.</p>\\n<p>§3º É responsabilidade do ALUNO manter atualizada a forma de pagamento cadastrada.</p>\\n<p>§4º Em caso de falha na cobrança ou inadimplência, o acesso do ALUNO poderá ser suspenso até regularização do pagamento.</p>\\n<p>§5º Em caso de atraso no pagamento incidirá multa de 2%, juros de 1% ao mês e correção monetária.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares são pagos à parte, em até 6 (seis) parcelas no cartão de crédito ou por PIX à vista, independentemente da cobrança mensal do plano.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o plano contratado possui fidelidade mínima de 12 (doze) meses, com cobrança realizada de forma recorrente mensal por cartão de crédito ou PIX Automático, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>• até o 4º mês de contrato: multa de 25% sobre o valor das mensalidades vincendas<br>\\n• entre o 5º e 6º mês: multa de 20% sobre o valor das mensalidades vincendas<br>\\n• entre o 7º e 12º mês: multa de 15% sobre o valor das mensalidades vincendas</p>\\n<p>§2º Após a solicitação formal de cancelamento, as cobranças recorrentes futuras serão interrompidas, permanecendo devido pelo ALUNO apenas:<br>\\nI – os valores já vencidos até a data do cancelamento;<br>\\nII – o valor correspondente à multa prevista nesta cláusula.</p>\\n<p>§3º O valor da multa poderá ser cobrado:<br>\\nI – em parcela única; ou<br>\\nII – de forma parcelada, a critério da CONTRATADA.</p>\\n<p>§4º Nos pagamentos realizados em modalidade recorrente, não haverá estorno de valores já cobrados, considerando que os serviços foram disponibilizados de forma proporcional ao período de utilização.</p>\\n<p>§5º Os serviços complementares seguem a cláusula 4ª-A: são cobrados à parte, não integram o cálculo da multa deste plano e seus créditos não são afetados pelo cancelamento.</p>\\n<p>§6º A taxa de recorrência incluída nas mensalidades não é restituível.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, ainda que a cobrança seja mensal, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 13/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90035-000", "CPF": "***.***.**725", "DIA": "13", "MES": "10", "NOME": "TESTE 2D2 RECORRENCIA", "EMAIL": "teste2d2@exemplo.invalid", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Rua de Teste, 1", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 453,90", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 24,90", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 7.066,80"},"hash_texto":"64ae8a9960b1d3a757a38fb21ea6e63df9fe69fe99563324e816f2c3a655bdea","valor_total_centavos":706680,"ip":"35.195.106.39","user_agent":"Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/141.0.7390.37 Safari/537.36","origem":"site","aceito_em":"2026-10-13T15:14:29.436791+00:00","invalidado_em":"2026-10-13T15:14:42.659654+00:00","motivo_invalidacao":"escolhas alteradas","created_at":"2026-10-13T15:14:29.436791+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"d722a603-2d77-4d7d-9b95-650d426f84e1","proposta_id":"129c309d-1a61-4b14-8c4a-0089534c53db","template_id":"ebeb495b-77cf-4a7a-9a4c-7b45fbbcdcfb","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: NICOLAS SQUEFF JANOVIK, Data de nascimento: 02/12/1989, CPF: 015.743.080-41, RG: , Endereço: Avenida Princesa Isabel, 358, Santana, Porto Alegre/RS – CEP 90620-001, E-mail: nicolas.janovik@gmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor: R$ 5.148,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 13/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90620-001", "CPF": "***.***.**041", "DIA": "13", "MES": "10", "NOME": "NICOLAS SQUEFF JANOVIK", "EMAIL": "nicolas.janovik@gmail.com", "BAIRRO": "Santana", "CIDADE": "Porto Alegre", "ENDERECO": "Avenida Princesa Isabel, 358", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 5.148,00", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "02/12/1989", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 5.148,00"},"hash_texto":"9d89cc4d45c6b4c7aa7f786acb96d3010cbc24d025cfe4b0a161cf0bc8057294","valor_total_centavos":514800,"ip":"189.6.248.107","user_agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/154.0.0.0 Safari/537.36","origem":"site","aceito_em":"2026-10-13T23:21:36.888962+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-13T23:21:36.888962+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"6db4bd54-d202-43f0-b2da-c2f352ff5a66","proposta_id":"426c321c-9526-4802-8de7-55689b73850c","template_id":"fa2064cf-605d-4ed6-82f9-19848a326dbe","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: Fortem Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO Nicolas Squeff Janovik, Data de nascimento: 02/12/1989, CPF: 015.743.080-41, RG: , Endereço: Avenida Princesa Isabel, 1155, Santana, Porto Alegre/RS – CEP 90620-001, E-mail: nicolas.janovik@gmail.com doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E DO PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPLANO: Start 2x<br>\\nFREQUÊNCIA: 2 (duas) vezes por semana<br>\\nVALOR MENSAL: R$ 499,00<br>\\nVIGÊNCIA: mensal, sem fidelidade, com renovação automática sucessiva até manifestação formal de cancelamento, nos termos deste contrato.</p>\\n<p>§1º O plano contratado opera no modelo de assinatura mensal com cobrança recorrente automática por cartão de crédito ou PIX Automático, conforme escolha do ALUNO no momento da contratação.</p>\\n<p>§2º A renovação ocorrerá automaticamente a cada período mensal, até o cancelamento, mantendo-se as condições contratuais vigentes, salvo comunicação prévia de alteração nos termos deste instrumento.</p>\\n<p>§3º É responsabilidade do ALUNO manter atualizada a forma de pagamento cadastrada.</p>\\n<p>§4º Em caso de falha na cobrança ou inadimplência, o acesso do ALUNO poderá ser suspenso até regularização do pagamento.</p>\\n<p>§5º Em caso de atraso no pagamento incidirá multa de 2%, juros de 1% ao mês e correção monetária.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares são pagos à parte, em até 6 (seis) parcelas no cartão de crédito ou por PIX à vista, independentemente da cobrança mensal do plano.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 5ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 6ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 7ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 8ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 9ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO PRAZO E DA RENOVAÇÃO</h2>\\n<p><strong>Cláusula 10ª</strong> – O presente contrato possui prazo indeterminado, iniciando-se na data de sua assinatura.</p>\\n<p><strong>Cláusula 11ª</strong> – O plano será renovado automaticamente a cada ciclo mensal mediante cobrança recorrente.</p>\\n<p><strong>Cláusula 12ª</strong> – A renovação ocorrerá automaticamente enquanto não houver solicitação formal de cancelamento pelo ALUNO.</p>\\n\\n<h2>DO CANCELAMENTO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do plano a qualquer momento, mediante comunicação pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º O cancelamento impedirá apenas as cobranças futuras, permanecendo o acesso do ALUNO até o término do ciclo mensal já pago.</p>\\n<p>§2º Em caso de cancelamento, eventual reativação futura estará sujeita aos valores vigentes no momento da nova contratação, não sendo garantida a manutenção de condições promocionais anteriormente concedidas.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 14ª</strong> – A licença do plano somente será permitida em caso de doença ou lesão devidamente comprovada por atestado médico.</p>\\n<p>§1º O período de licença poderá ser concedido por até 30 (trinta) dias corridos.</p>\\n<p>§2º O prazo de licença será acrescido ao final do contrato, prorrogando-se automaticamente a sua vigência pelo mesmo período.</p>\\n<p>§3º A licença poderá ser solicitada uma única vez durante a vigência contratual.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 1 (um) mês, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda. Contudo, eventual redução de frequência semanal poderá ser realizada mediante formalização de novo contrato ao término da vigência do contrato atual, observadas as condições comerciais então vigentes à época da nova contratação.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos mensais de treino, liberados a cada mês de vigência:<br>\\n1 (uma) vez por semana: 4 créditos<br>\\n2 (duas) vezes por semana: 8 créditos<br>\\n3 (três) vezes por semana: 12 créditos<br>\\nplano livre: acesso ilimitado<br>\\nOs créditos de cada mês não utilizados não se acumulam para o mês seguinte.</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, sendo o contrato vigente na modalidade de cobrança recorrente mensal automaticamente cancelado a partir da ativação do novo plano, permanecendo exigíveis:<br>\\nI – os valores eventualmente vencidos até a data da migração;<br>\\nII – eventual diferença financeira necessária para adequação ao novo plano contratado, a qual deverá ser regularizada previamente à ativação do novo contrato.</p>\\n<p>§5º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§6º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos mensais de treino e benefícios adicionais vinculados à política comercial vigente, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§7º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DO AJUSTE DE VALORES</h2>\\n<p><strong>Cláusula 16ª</strong> – A CONTRATADA poderá alterar os valores dos planos mediante comunicação prévia ao ALUNO com antecedência mínima de 30 dias antes da próxima cobrança.</p>\\n<p>Parágrafo único – Caso o ALUNO não concorde com o novo valor, poderá solicitar o cancelamento antes do início do novo ciclo de cobrança.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que passa a integrar o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90620-001", "CPF": "***.***.**041", "DIA": "14", "MES": "10", "NOME": "Nicolas Squeff Janovik", "EMAIL": "nicolas.janovik@gmail.com", "BAIRRO": "Santana", "CIDADE": "Porto Alegre", "ENDERECO": "Avenida Princesa Isabel, 1155", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "", "VALOR_MENSAL": "R$ 499,00", "NOME_CONTRATO": "Start 2x", "DATA_NASCIMENTO": "02/12/1989", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 499,00"},"hash_texto":"aee547a16ea45d50ef50f454dc020342e8ef353c1cfc694f712da675bc4b2436","valor_total_centavos":49900,"ip":"189.6.233.112","user_agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36","origem":"site","aceito_em":"2026-10-14T09:24:50.079817+00:00","invalidado_em":"2026-10-14T09:34:42.518982+00:00","motivo_invalidacao":"escolhas alteradas","created_at":"2026-10-14T09:24:50.079817+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"94dd12aa-e54b-40b8-96cc-944b458aba70","proposta_id":"86a61427-7880-4d4d-b338-41cfc5a653b1","template_id":"225c44c2-2da6-4f93-aa63-87c4f812908d","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: NICOLAS TESTE, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Av. Independência, 100, Centro, Porto Alegre/RS – CEP 90000-000, E-mail: nicolas_ja@hotmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor mensal: R$ 453,90 (já incluída a taxa de recorrência de R$ 24,90)<br>\\nVigência: 12 (doze) meses, com fidelidade mínima de 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano possui condição comercial especial em razão da fidelidade contratual mínima de 12 (doze) meses, sendo realizado por meio de cobrança recorrente mensal automática por cartão de crédito ou PIX Automático, conforme a forma de pagamento cadastrada pelo ALUNO, não se caracterizando como contratação mensal independente, mas como forma de pagamento parcelada do período contratual total.</p>\\n<p>§2º O valor mensal inclui a taxa de recorrência de R$ 24,90, que não é restituível em nenhuma hipótese.</p>\\n<p>§3º É responsabilidade do ALUNO manter atualizada a forma de pagamento cadastrada.</p>\\n<p>§4º Em caso de falha na cobrança ou inadimplência, o acesso do ALUNO poderá ser suspenso até regularização do pagamento.</p>\\n<p>§5º Em caso de atraso no pagamento incidirá multa de 2%, juros de 1% ao mês e correção monetária.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares são pagos à parte, em até 6 (seis) parcelas no cartão de crédito ou por PIX à vista, independentemente da cobrança mensal do plano.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o plano contratado possui fidelidade mínima de 12 (doze) meses, com cobrança realizada de forma recorrente mensal por cartão de crédito ou PIX Automático, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>• até o 4º mês de contrato: multa de 25% sobre o valor das mensalidades vincendas<br>\\n• entre o 5º e 6º mês: multa de 20% sobre o valor das mensalidades vincendas<br>\\n• entre o 7º e 12º mês: multa de 15% sobre o valor das mensalidades vincendas</p>\\n<p>§2º Após a solicitação formal de cancelamento, as cobranças recorrentes futuras serão interrompidas, permanecendo devido pelo ALUNO apenas:<br>\\nI – os valores já vencidos até a data do cancelamento;<br>\\nII – o valor correspondente à multa prevista nesta cláusula.</p>\\n<p>§3º O valor da multa poderá ser cobrado:<br>\\nI – em parcela única; ou<br>\\nII – de forma parcelada, a critério da CONTRATADA.</p>\\n<p>§4º Nos pagamentos realizados em modalidade recorrente, não haverá estorno de valores já cobrados, considerando que os serviços foram disponibilizados de forma proporcional ao período de utilização.</p>\\n<p>§5º Os serviços complementares seguem a cláusula 4ª-A: são cobrados à parte, não integram o cálculo da multa deste plano e seus créditos não são afetados pelo cancelamento.</p>\\n<p>§6º A taxa de recorrência incluída nas mensalidades não é restituível.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, ainda que a cobrança seja mensal, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90000-000", "CPF": "***.***.**725", "DIA": "14", "MES": "10", "NOME": "NICOLAS TESTE", "EMAIL": "nicolas_ja@hotmail.com", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Av. Independência, 100", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 453,90", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 24,90", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 7.066,80"},"hash_texto":"84137f23627a696a2126a3235d5c3a23aa3ee74dd2f84e646055572f88c5ce1c","valor_total_centavos":706680,"ip":"34.178.219.190","user_agent":"Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/141.0.7390.37 Safari/537.36","origem":"site","aceito_em":"2026-10-14T13:36:42.215104+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-14T13:36:42.215104+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"164830fd-f9d0-4016-b9d2-d6b29045d94c","proposta_id":"a6811b24-613f-499a-8740-ae41e9a539e5","template_id":"225c44c2-2da6-4f93-aa63-87c4f812908d","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: NICOLAS TESTE, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Av. Independência, 100, Centro, Porto Alegre/RS – CEP 90000-000, E-mail: nicolas_ja@hotmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor mensal: R$ 453,90 (já incluída a taxa de recorrência de R$ 24,90)<br>\\nVigência: 12 (doze) meses, com fidelidade mínima de 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano possui condição comercial especial em razão da fidelidade contratual mínima de 12 (doze) meses, sendo realizado por meio de cobrança recorrente mensal automática por cartão de crédito ou PIX Automático, conforme a forma de pagamento cadastrada pelo ALUNO, não se caracterizando como contratação mensal independente, mas como forma de pagamento parcelada do período contratual total.</p>\\n<p>§2º O valor mensal inclui a taxa de recorrência de R$ 24,90, que não é restituível em nenhuma hipótese.</p>\\n<p>§3º É responsabilidade do ALUNO manter atualizada a forma de pagamento cadastrada.</p>\\n<p>§4º Em caso de falha na cobrança ou inadimplência, o acesso do ALUNO poderá ser suspenso até regularização do pagamento.</p>\\n<p>§5º Em caso de atraso no pagamento incidirá multa de 2%, juros de 1% ao mês e correção monetária.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares são pagos à parte, em até 6 (seis) parcelas no cartão de crédito ou por PIX à vista, independentemente da cobrança mensal do plano.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o plano contratado possui fidelidade mínima de 12 (doze) meses, com cobrança realizada de forma recorrente mensal por cartão de crédito ou PIX Automático, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>• até o 4º mês de contrato: multa de 25% sobre o valor das mensalidades vincendas<br>\\n• entre o 5º e 6º mês: multa de 20% sobre o valor das mensalidades vincendas<br>\\n• entre o 7º e 12º mês: multa de 15% sobre o valor das mensalidades vincendas</p>\\n<p>§2º Após a solicitação formal de cancelamento, as cobranças recorrentes futuras serão interrompidas, permanecendo devido pelo ALUNO apenas:<br>\\nI – os valores já vencidos até a data do cancelamento;<br>\\nII – o valor correspondente à multa prevista nesta cláusula.</p>\\n<p>§3º O valor da multa poderá ser cobrado:<br>\\nI – em parcela única; ou<br>\\nII – de forma parcelada, a critério da CONTRATADA.</p>\\n<p>§4º Nos pagamentos realizados em modalidade recorrente, não haverá estorno de valores já cobrados, considerando que os serviços foram disponibilizados de forma proporcional ao período de utilização.</p>\\n<p>§5º Os serviços complementares seguem a cláusula 4ª-A: são cobrados à parte, não integram o cálculo da multa deste plano e seus créditos não são afetados pelo cancelamento.</p>\\n<p>§6º A taxa de recorrência incluída nas mensalidades não é restituível.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, ainda que a cobrança seja mensal, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90000-000", "CPF": "***.***.**725", "DIA": "14", "MES": "10", "NOME": "NICOLAS TESTE", "EMAIL": "nicolas_ja@hotmail.com", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Av. Independência, 100", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 453,90", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 24,90", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 7.066,80"},"hash_texto":"84137f23627a696a2126a3235d5c3a23aa3ee74dd2f84e646055572f88c5ce1c","valor_total_centavos":706680,"ip":"34.178.219.190","user_agent":"Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/141.0.7390.37 Safari/537.36","origem":"site","aceito_em":"2026-10-14T14:06:20.043682+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-14T14:06:20.043682+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"dc1a9b80-867e-4055-9cdb-5d9dce606189","proposta_id":"88afaa87-d4b9-4e0f-80be-5ba979c9064b","template_id":"225c44c2-2da6-4f93-aa63-87c4f812908d","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: NICOLAS TESTE, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Av. Independência, 100, Centro, Porto Alegre/RS – CEP 90000-000, E-mail: nicolas_ja@hotmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor mensal: R$ 453,90 (já incluída a taxa de recorrência de R$ 24,90)<br>\\nVigência: 12 (doze) meses, com fidelidade mínima de 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano possui condição comercial especial em razão da fidelidade contratual mínima de 12 (doze) meses, sendo realizado por meio de cobrança recorrente mensal automática por cartão de crédito ou PIX Automático, conforme a forma de pagamento cadastrada pelo ALUNO, não se caracterizando como contratação mensal independente, mas como forma de pagamento parcelada do período contratual total.</p>\\n<p>§2º O valor mensal inclui a taxa de recorrência de R$ 24,90, que não é restituível em nenhuma hipótese.</p>\\n<p>§3º É responsabilidade do ALUNO manter atualizada a forma de pagamento cadastrada.</p>\\n<p>§4º Em caso de falha na cobrança ou inadimplência, o acesso do ALUNO poderá ser suspenso até regularização do pagamento.</p>\\n<p>§5º Em caso de atraso no pagamento incidirá multa de 2%, juros de 1% ao mês e correção monetária.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares são pagos à parte, em até 6 (seis) parcelas no cartão de crédito ou por PIX à vista, independentemente da cobrança mensal do plano.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o plano contratado possui fidelidade mínima de 12 (doze) meses, com cobrança realizada de forma recorrente mensal por cartão de crédito ou PIX Automático, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>• até o 4º mês de contrato: multa de 25% sobre o valor das mensalidades vincendas<br>\\n• entre o 5º e 6º mês: multa de 20% sobre o valor das mensalidades vincendas<br>\\n• entre o 7º e 12º mês: multa de 15% sobre o valor das mensalidades vincendas</p>\\n<p>§2º Após a solicitação formal de cancelamento, as cobranças recorrentes futuras serão interrompidas, permanecendo devido pelo ALUNO apenas:<br>\\nI – os valores já vencidos até a data do cancelamento;<br>\\nII – o valor correspondente à multa prevista nesta cláusula.</p>\\n<p>§3º O valor da multa poderá ser cobrado:<br>\\nI – em parcela única; ou<br>\\nII – de forma parcelada, a critério da CONTRATADA.</p>\\n<p>§4º Nos pagamentos realizados em modalidade recorrente, não haverá estorno de valores já cobrados, considerando que os serviços foram disponibilizados de forma proporcional ao período de utilização.</p>\\n<p>§5º Os serviços complementares seguem a cláusula 4ª-A: são cobrados à parte, não integram o cálculo da multa deste plano e seus créditos não são afetados pelo cancelamento.</p>\\n<p>§6º A taxa de recorrência incluída nas mensalidades não é restituível.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, ainda que a cobrança seja mensal, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90000-000", "CPF": "***.***.**725", "DIA": "14", "MES": "10", "NOME": "NICOLAS TESTE", "EMAIL": "nicolas_ja@hotmail.com", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Av. Independência, 100", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 453,90", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 24,90", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 7.066,80"},"hash_texto":"84137f23627a696a2126a3235d5c3a23aa3ee74dd2f84e646055572f88c5ce1c","valor_total_centavos":706680,"ip":"34.178.219.190","user_agent":"Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/141.0.7390.37 Safari/537.36","origem":"site","aceito_em":"2026-10-14T14:07:22.682414+00:00","invalidado_em":"2026-10-14T14:12:44.57113+00:00","motivo_invalidacao":"escolhas alteradas","created_at":"2026-10-14T14:07:22.682414+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"dac39e69-9822-49f8-ab6d-73dc0497a5d9","proposta_id":"88afaa87-d4b9-4e0f-80be-5ba979c9064b","template_id":"225c44c2-2da6-4f93-aa63-87c4f812908d","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: NICOLAS TESTE, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Av. Independência, 100, Centro, Porto Alegre/RS – CEP 90000-000, E-mail: nicolas_ja@hotmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor mensal: R$ 453,90 (já incluída a taxa de recorrência de R$ 24,90)<br>\\nVigência: 12 (doze) meses, com fidelidade mínima de 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano possui condição comercial especial em razão da fidelidade contratual mínima de 12 (doze) meses, sendo realizado por meio de cobrança recorrente mensal automática por cartão de crédito ou PIX Automático, conforme a forma de pagamento cadastrada pelo ALUNO, não se caracterizando como contratação mensal independente, mas como forma de pagamento parcelada do período contratual total.</p>\\n<p>§2º O valor mensal inclui a taxa de recorrência de R$ 24,90, que não é restituível em nenhuma hipótese.</p>\\n<p>§3º É responsabilidade do ALUNO manter atualizada a forma de pagamento cadastrada.</p>\\n<p>§4º Em caso de falha na cobrança ou inadimplência, o acesso do ALUNO poderá ser suspenso até regularização do pagamento.</p>\\n<p>§5º Em caso de atraso no pagamento incidirá multa de 2%, juros de 1% ao mês e correção monetária.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares são pagos à parte, em até 6 (seis) parcelas no cartão de crédito ou por PIX à vista, independentemente da cobrança mensal do plano.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o plano contratado possui fidelidade mínima de 12 (doze) meses, com cobrança realizada de forma recorrente mensal por cartão de crédito ou PIX Automático, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>• até o 4º mês de contrato: multa de 25% sobre o valor das mensalidades vincendas<br>\\n• entre o 5º e 6º mês: multa de 20% sobre o valor das mensalidades vincendas<br>\\n• entre o 7º e 12º mês: multa de 15% sobre o valor das mensalidades vincendas</p>\\n<p>§2º Após a solicitação formal de cancelamento, as cobranças recorrentes futuras serão interrompidas, permanecendo devido pelo ALUNO apenas:<br>\\nI – os valores já vencidos até a data do cancelamento;<br>\\nII – o valor correspondente à multa prevista nesta cláusula.</p>\\n<p>§3º O valor da multa poderá ser cobrado:<br>\\nI – em parcela única; ou<br>\\nII – de forma parcelada, a critério da CONTRATADA.</p>\\n<p>§4º Nos pagamentos realizados em modalidade recorrente, não haverá estorno de valores já cobrados, considerando que os serviços foram disponibilizados de forma proporcional ao período de utilização.</p>\\n<p>§5º Os serviços complementares seguem a cláusula 4ª-A: são cobrados à parte, não integram o cálculo da multa deste plano e seus créditos não são afetados pelo cancelamento.</p>\\n<p>§6º A taxa de recorrência incluída nas mensalidades não é restituível.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, ainda que a cobrança seja mensal, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90000-000", "CPF": "***.***.**725", "DIA": "14", "MES": "10", "NOME": "NICOLAS TESTE", "EMAIL": "nicolas_ja@hotmail.com", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Av. Independência, 100", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 453,90", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 24,90", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 7.066,80"},"hash_texto":"84137f23627a696a2126a3235d5c3a23aa3ee74dd2f84e646055572f88c5ce1c","valor_total_centavos":706680,"ip":"34.178.219.190","user_agent":"Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/141.0.7390.37 Safari/537.36","origem":"site","aceito_em":"2026-10-14T14:17:52.886251+00:00","invalidado_em":"2026-10-14T14:30:18.71904+00:00","motivo_invalidacao":"escolhas alteradas","created_at":"2026-10-14T14:17:52.886251+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"10a54f12-e4a9-4b30-b79d-b62af33fbb7e","proposta_id":"88afaa87-d4b9-4e0f-80be-5ba979c9064b","template_id":"ebeb495b-77cf-4a7a-9a4c-7b45fbbcdcfb","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: NICOLAS TESTE, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Av. Independência, 100, Centro, Porto Alegre/RS – CEP 90000-000, E-mail: nicolas_ja@hotmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor: R$ 5.148,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90000-000", "CPF": "***.***.**725", "DIA": "14", "MES": "10", "NOME": "NICOLAS TESTE", "EMAIL": "nicolas_ja@hotmail.com", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Av. Independência, 100", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 5.148,00", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 5.148,00"},"hash_texto":"68b59ad90a5c6cc67f2d994b4d86aeeed19edd5f8e4f2e49f90cd650a1bf3f9c","valor_total_centavos":514800,"ip":"34.178.219.190","user_agent":"python-requests/2.32.5","origem":"site","aceito_em":"2026-10-14T14:30:25.288035+00:00","invalidado_em":"2026-10-14T14:30:32.734029+00:00","motivo_invalidacao":"escolhas alteradas","created_at":"2026-10-14T14:30:25.288035+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"1de75595-61d8-4e3c-9943-6275c1df941e","proposta_id":"88afaa87-d4b9-4e0f-80be-5ba979c9064b","template_id":"225c44c2-2da6-4f93-aa63-87c4f812908d","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: NICOLAS TESTE, Data de nascimento: 01/01/1990, CPF: 529.982.247-25, RG: , Endereço: Av. Independência, 100, Centro, Porto Alegre/RS – CEP 90000-000, E-mail: nicolas_ja@hotmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor mensal: R$ 453,90 (já incluída a taxa de recorrência de R$ 24,90)<br>\\nVigência: 12 (doze) meses, com fidelidade mínima de 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano possui condição comercial especial em razão da fidelidade contratual mínima de 12 (doze) meses, sendo realizado por meio de cobrança recorrente mensal automática por cartão de crédito ou PIX Automático, conforme a forma de pagamento cadastrada pelo ALUNO, não se caracterizando como contratação mensal independente, mas como forma de pagamento parcelada do período contratual total.</p>\\n<p>§2º O valor mensal inclui a taxa de recorrência de R$ 24,90, que não é restituível em nenhuma hipótese.</p>\\n<p>§3º É responsabilidade do ALUNO manter atualizada a forma de pagamento cadastrada.</p>\\n<p>§4º Em caso de falha na cobrança ou inadimplência, o acesso do ALUNO poderá ser suspenso até regularização do pagamento.</p>\\n<p>§5º Em caso de atraso no pagamento incidirá multa de 2%, juros de 1% ao mês e correção monetária.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares são pagos à parte, em até 6 (seis) parcelas no cartão de crédito ou por PIX à vista, independentemente da cobrança mensal do plano.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o plano contratado possui fidelidade mínima de 12 (doze) meses, com cobrança realizada de forma recorrente mensal por cartão de crédito ou PIX Automático, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>• até o 4º mês de contrato: multa de 25% sobre o valor das mensalidades vincendas<br>\\n• entre o 5º e 6º mês: multa de 20% sobre o valor das mensalidades vincendas<br>\\n• entre o 7º e 12º mês: multa de 15% sobre o valor das mensalidades vincendas</p>\\n<p>§2º Após a solicitação formal de cancelamento, as cobranças recorrentes futuras serão interrompidas, permanecendo devido pelo ALUNO apenas:<br>\\nI – os valores já vencidos até a data do cancelamento;<br>\\nII – o valor correspondente à multa prevista nesta cláusula.</p>\\n<p>§3º O valor da multa poderá ser cobrado:<br>\\nI – em parcela única; ou<br>\\nII – de forma parcelada, a critério da CONTRATADA.</p>\\n<p>§4º Nos pagamentos realizados em modalidade recorrente, não haverá estorno de valores já cobrados, considerando que os serviços foram disponibilizados de forma proporcional ao período de utilização.</p>\\n<p>§5º Os serviços complementares seguem a cláusula 4ª-A: são cobrados à parte, não integram o cálculo da multa deste plano e seus créditos não são afetados pelo cancelamento.</p>\\n<p>§6º A taxa de recorrência incluída nas mensalidades não é restituível.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, ainda que a cobrança seja mensal, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90000-000", "CPF": "***.***.**725", "DIA": "14", "MES": "10", "NOME": "NICOLAS TESTE", "EMAIL": "nicolas_ja@hotmail.com", "BAIRRO": "Centro", "CIDADE": "Porto Alegre", "ENDERECO": "Av. Independência, 100", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 453,90", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "01/01/1990", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 24,90", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 7.066,80"},"hash_texto":"84137f23627a696a2126a3235d5c3a23aa3ee74dd2f84e646055572f88c5ce1c","valor_total_centavos":706680,"ip":"34.178.219.190","user_agent":"python-requests/2.32.5","origem":"site","aceito_em":"2026-10-14T14:30:36.36081+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-14T14:30:36.36081+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"e62ff9e4-09ff-4314-9445-922e6b723bde","proposta_id":"2c90c63c-8b6b-44ee-9bf8-04787ee2e78c","template_id":"38180919-6f31-462a-8374-08975aa7d379","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: Nicolas Squeff Janovik, Data de nascimento: 02/12/1989, CPF: 015.743.080-41, RG: , Endereço: Avenida Princesa Isabel, 1155, Santana, Porto Alegre/RS – CEP 90620-001, E-mail: nicolas.janovik@gmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Pro 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor: R$ 5.988,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>2 avaliações funcionais (1º e 6º mês)</li>\\n<li>20 dias de licença</li>\\n<li>fixação de horários</li>\\n<li>4 sessões por mês de bota de compressão pneumática, agendáveis no portal, não acumuláveis</li>\\n<li>brinde: camiseta e garrafinha</li>\\n<li>condições especiais no Clube Fortem</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA REPOSIÇÃO DE CRÉDITOS</h2>\\n<p><strong>Cláusula 15ª-A</strong> – Ao final da vigência deste contrato, 50% (cinquenta por cento) do saldo de créditos de treino não utilizados, arredondado para cima, será transferido ao novo plano contratado pelo ALUNO, para uso conforme a vigência deste novo plano, desde que o novo plano seja contratado em até 30 (trinta) dias corridos após o término da vigência deste contrato; encerrado esse prazo, o saldo não será transferido.</p>\\n<p>Parágrafo único – A reposição vale somente para créditos de treino, não se aplicando a créditos de nutrição, reabilitação ou avaliações.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 20 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90620-001", "CPF": "***.***.**041", "DIA": "14", "MES": "10", "NOME": "Nicolas Squeff Janovik", "EMAIL": "nicolas.janovik@gmail.com", "BAIRRO": "Santana", "CIDADE": "Porto Alegre", "ENDERECO": "Avenida Princesa Isabel, 1155", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "20", "VALOR_MENSAL": "R$ 5.988,00", "NOME_CONTRATO": "Pro 2x", "DATA_NASCIMENTO": "02/12/1989", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>2 avaliações funcionais (1º e 6º mês)</li>\\n<li>20 dias de licença</li>\\n<li>fixação de horários</li>\\n<li>4 sessões por mês de bota de compressão pneumática, agendáveis no portal, não acumuláveis</li>\\n<li>brinde: camiseta e garrafinha</li>\\n<li>condições especiais no Clube Fortem</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "<h2>DA REPOSIÇÃO DE CRÉDITOS</h2>\\n<p><strong>Cláusula 15ª-A</strong> – Ao final da vigência deste contrato, 50% (cinquenta por cento) do saldo de créditos de treino não utilizados, arredondado para cima, será transferido ao novo plano contratado pelo ALUNO, para uso conforme a vigência deste novo plano, desde que o novo plano seja contratado em até 30 (trinta) dias corridos após o término da vigência deste contrato; encerrado esse prazo, o saldo não será transferido.</p>\\n<p>Parágrafo único – A reposição vale somente para créditos de treino, não se aplicando a créditos de nutrição, reabilitação ou avaliações.</p>\\n\\n", "VALOR_FINAL_CONTRATO": "R$ 5.988,00"},"hash_texto":"80fa1fcc8925fbcd9fe0fc6e27cb4d90f9521ef7b426975d78e8bcfe3a8b9a48","valor_total_centavos":598800,"ip":"189.6.233.112","user_agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36","origem":"site","aceito_em":"2026-10-14T15:42:13.112299+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-14T15:42:13.112299+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"fc1161d5-4c2a-4ad4-b5a8-fe0aabc3eb18","proposta_id":"8f9441a2-8baf-4b55-b704-e896b877e8c9","template_id":"ebeb495b-77cf-4a7a-9a4c-7b45fbbcdcfb","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: Nicolas Squeff Janovik, Data de nascimento: 02/12/1989, CPF: 015.743.080-41, RG: , Endereço: Avenida Princesa Isabel, 1155, Santana, Porto Alegre/RS – CEP 90620-001, E-mail: nicolas.janovik@gmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor: R$ 5.148,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90620-001", "CPF": "***.***.**041", "DIA": "14", "MES": "10", "NOME": "Nicolas Squeff Janovik", "EMAIL": "nicolas.janovik@gmail.com", "BAIRRO": "Santana", "CIDADE": "Porto Alegre", "ENDERECO": "Avenida Princesa Isabel, 1155", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 5.148,00", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "02/12/1989", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 5.148,00"},"hash_texto":"cd0187545e4dbd383cebe11ee275908f48bc1b596faf61a4fdfdf653b7842cc4","valor_total_centavos":514800,"ip":"189.6.233.112","user_agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36","origem":"site","aceito_em":"2026-10-14T15:52:40.702727+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-14T15:52:40.702727+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"02e61a1a-d037-4f07-bec3-71f7ef6fd06d","proposta_id":"7d5e8c15-9c34-42b5-a807-ec7bc10f84ab","template_id":"ebeb495b-77cf-4a7a-9a4c-7b45fbbcdcfb","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: Nicolas Squeff Janovik, Data de nascimento: 02/12/1989, CPF: 015.743.080-41, RG: , Endereço: Avenida Princesa Isabel, 1155, Santana, Porto Alegre/RS – CEP 90620-001, E-mail: nicolas.janovik@gmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor: R$ 5.148,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90620-001", "CPF": "***.***.**041", "DIA": "14", "MES": "10", "NOME": "Nicolas Squeff Janovik", "EMAIL": "nicolas.janovik@gmail.com", "BAIRRO": "Santana", "CIDADE": "Porto Alegre", "ENDERECO": "Avenida Princesa Isabel, 1155", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 5.148,00", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "02/12/1989", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 5.148,00"},"hash_texto":"cd0187545e4dbd383cebe11ee275908f48bc1b596faf61a4fdfdf653b7842cc4","valor_total_centavos":514800,"ip":"189.6.233.112","user_agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36","origem":"site","aceito_em":"2026-10-14T15:59:14.400977+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-14T15:59:14.400977+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"1033a05f-69b9-4591-ab62-5f067b1a0ddb","proposta_id":"ba9931d5-2bf4-42fa-af9e-04a7ebf9f0e7","template_id":"ebeb495b-77cf-4a7a-9a4c-7b45fbbcdcfb","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: Nicolas Squeff Janovik, Data de nascimento: 02/12/1989, CPF: 015.743.080-41, RG: , Endereço: Avenida Princesa Isabel, 1155, Santana, Porto Alegre/RS – CEP 90620-001, E-mail: nicolas.janovik@gmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor: R$ 5.148,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90620-001", "CPF": "***.***.**041", "DIA": "14", "MES": "10", "NOME": "Nicolas Squeff Janovik", "EMAIL": "nicolas.janovik@gmail.com", "BAIRRO": "Santana", "CIDADE": "Porto Alegre", "ENDERECO": "Avenida Princesa Isabel, 1155", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 5.148,00", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "02/12/1989", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 5.148,00"},"hash_texto":"cd0187545e4dbd383cebe11ee275908f48bc1b596faf61a4fdfdf653b7842cc4","valor_total_centavos":514800,"ip":"189.6.233.112","user_agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36","origem":"site","aceito_em":"2026-10-14T16:30:35.429452+00:00","invalidado_em":"2026-10-14T16:41:31.771985+00:00","motivo_invalidacao":"escolhas alteradas","created_at":"2026-10-14T16:30:35.429452+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"74be0754-a8d2-4cb3-a65d-729f6eddeceb","proposta_id":"ba9931d5-2bf4-42fa-af9e-04a7ebf9f0e7","template_id":"38180919-6f31-462a-8374-08975aa7d379","template_versao":1,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: Nicolas Squeff Janovik, Data de nascimento: 02/12/1989, CPF: 015.743.080-41, RG: , Endereço: Avenida Princesa Isabel, 1155, Santana, Porto Alegre/RS – CEP 90620-001, E-mail: nicolas.janovik@gmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se realizou avaliação médica prévia ou se opta, por sua conta e risco, pela prática de atividades físicas sem avaliação médica recente.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Pro Livre<br>\\nFrequência: Livre<br>\\nValor: R$ 8.388,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>2 avaliações funcionais (1º e 6º mês)</li>\\n<li>20 dias de licença</li>\\n<li>fixação de horários</li>\\n<li>4 sessões por mês de bota de compressão pneumática, agendáveis no portal, não acumuláveis</li>\\n<li>brinde: camiseta e garrafinha</li>\\n<li>condições especiais no Clube Fortem</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 20 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90620-001", "CPF": "***.***.**041", "DIA": "14", "MES": "10", "NOME": "Nicolas Squeff Janovik", "EMAIL": "nicolas.janovik@gmail.com", "BAIRRO": "Santana", "CIDADE": "Porto Alegre", "ENDERECO": "Avenida Princesa Isabel, 1155", "FREQUENCIA": "Livre", "LICENCA_DIAS": "20", "VALOR_MENSAL": "R$ 8.388,00", "NOME_CONTRATO": "Pro Livre", "DATA_NASCIMENTO": "02/12/1989", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>2 avaliações funcionais (1º e 6º mês)</li>\\n<li>20 dias de licença</li>\\n<li>fixação de horários</li>\\n<li>4 sessões por mês de bota de compressão pneumática, agendáveis no portal, não acumuláveis</li>\\n<li>brinde: camiseta e garrafinha</li>\\n<li>condições especiais no Clube Fortem</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 8.388,00"},"hash_texto":"f72680260227675ccf089e85ff12c6a0f4f2d17ba403f84fc92a9311a5e8ba2e","valor_total_centavos":838800,"ip":"189.6.233.112","user_agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36","origem":"site","aceito_em":"2026-10-14T16:42:01.257295+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-14T16:42:01.257295+00:00","anexo":null,"anexo_versao":null,"anexo_assinatura":null}');
insert into public.propostas_2027_aceites select * from json_populate_record(null::public.propostas_2027_aceites, E'{"id":"9ebba6f4-ba19-4618-8b29-9c074cc8163a","proposta_id":"7ccbeb5f-ddea-452f-ab23-76c3d1b2d27c","template_id":"ebeb495b-77cf-4a7a-9a4c-7b45fbbcdcfb","template_versao":2,"regulamento_versao":1,"conteudo_html":"<h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\\n<p>Pelo presente instrumento particular, de um lado: FORTEM Treinamento Físico LTDA, pessoa jurídica de direito privado, inscrita no CNPJ nº 26.502.263/0001-92, com sede na Av. Independência, 358 – Porto Alegre/RS, neste ato representada na forma de seu contrato social, doravante denominada CONTRATADA, e de outro lado ALUNO: Nicolas Squeff Janovik, Data de nascimento: 02/12/1989, CPF: 015.743.080-41, RG: , Endereço: Avenida Princesa Isabel, 1155, Santana, Porto Alegre/RS – CEP 90620-001, E-mail: nicolas.janovik@gmail.com, doravante denominado ALUNO, celebram o presente contrato de prestação de serviços mediante as seguintes cláusulas e condições.</p>\\n\\n<h2>DO OBJETO</h2>\\n<p><strong>Cláusula 1ª</strong> – O presente contrato tem por objeto a prestação de serviços de treinamento físico funcional, bem como a utilização das instalações, equipamentos e metodologia da CONTRATADA, conforme os limites e condições do plano escolhido pelo ALUNO.</p>\\n<p>§1º Está incluso na prestação de serviços a condução e supervisão das práticas de atividades físicas por profissionais qualificados.</p>\\n<p>§2º O ALUNO terá direito de participar das atividades disponibilizadas pelo plano contratado, observadas eventuais restrições pessoais.</p>\\n<p>§3º A CONTRATADA poderá promover ajustes em horários, instrutores, metodologia ou funcionamento sempre que necessário para melhor organização das atividades.</p>\\n<p>§4º O ALUNO compromete-se a respeitar as orientações técnicas dos instrutores e as normas do regulamento interno da CONTRATADA.</p>\\n<p>§5º A CONTRATADA poderá impedir o acesso do ALUNO às instalações caso haja descumprimento das regras contratuais ou do regulamento interno.</p>\\n\\n<h2>DAS DISPOSIÇÕES INICIAIS</h2>\\n<p><strong>Cláusula 2ª</strong> – O ALUNO declara ter recebido previamente todas as informações relativas aos planos oferecidos pela CONTRATADA e opta livremente pelo plano contratado.</p>\\n\\n<h2>DAS CONDIÇÕES DE SAÚDE</h2>\\n<p><strong>Cláusula 3ª</strong> – O ALUNO declara estar ciente de que a prática de atividades físicas envolve riscos inerentes e imprevisíveis, incluindo, mas não se limitando, a lesões musculares, articulares, contusões, quedas, mal súbito e demais eventos adversos decorrentes de esforço físico, ainda que haja orientação e acompanhamento profissional adequado.</p>\\n<p>§1º O ALUNO declara, sob sua exclusiva responsabilidade, que se encontra em condições físicas e de saúde adequadas para a prática de atividades físicas, comprometendo-se a informar previamente à CONTRATADA, por escrito, a existência de quaisquer limitações, restrições médicas, patologias, lesões ou condições que possam interferir na realização das atividades.</p>\\n<p>§2º O ALUNO obriga-se a comunicar imediata e formalmente à CONTRATADA qualquer alteração superveniente em seu estado de saúde que possa impactar na prática das atividades, responsabilizando-se integralmente por eventuais omissões.</p>\\n<p>§3º Na hipótese de o ALUNO possuir restrições médicas, estar em tratamento clínico ou fazer uso de medicação que possa influenciar seu desempenho ou segurança, deverá apresentar, previamente ao início ou continuidade das atividades, atestado ou liberação médica expressa para a prática de exercícios físicos, isentando a CONTRATADA de qualquer responsabilidade em caso de descumprimento desta obrigação.</p>\\n<p>§4º Em caso de cirurgia, tratamento médico relevante ou ocorrência de lesão durante a vigência deste contrato, o ALUNO somente poderá retornar às atividades mediante apresentação de liberação médica formal, responsabilizando-se por quaisquer consequências decorrentes do retorno sem a devida autorização.</p>\\n<p>§5º A omissão, inexatidão ou prestação incompleta de informações relativas ao estado de saúde do ALUNO implicará na assunção integral dos riscos por parte deste, eximindo a CONTRATADA, seus sócios, colaboradores e prepostos de quaisquer responsabilidades por danos, prejuízos ou intercorrências daí decorrentes.</p>\\n<p>§6º Em caso de mal súbito, acidente ou qualquer situação emergencial ocorrida nas dependências da CONTRATADA ou durante atividades por ela orientadas, o ALUNO autoriza, de forma expressa e irrevogável, o acionamento de serviços de atendimento médico de emergência, declarando-se ciente de que todas as despesas decorrentes serão de sua exclusiva responsabilidade ou de seu responsável legal.</p>\\n<p>§7º O ALUNO reconhece e concorda que o preenchimento e a assinatura do ANEXO I – Declaração de Aptidão Física e Uso de Imagem constituem condição essencial para a prestação dos serviços, obrigando-se a assinalar expressamente o campo referente à Avaliação Médica, declarando se possui ou não restrições médicas à prática de atividade física, apresentando atestado quando houver restrição.</p>\\n<p>§8º A ausência de preenchimento, o preenchimento incorreto ou a recusa em assinalar o item referido no parágrafo anterior poderá, a exclusivo critério da CONTRATADA, impedir o início ou a continuidade da prestação dos serviços, sem que isso gere qualquer direito a indenização, reembolso ou compensação ao ALUNO.</p>\\n\\n<h2>DO PLANO CONTRATADO E PAGAMENTO</h2>\\n<p><strong>Cláusula 4ª</strong> – O ALUNO contrata o seguinte plano:<br>\\nPlano contratado: Power 2x<br>\\nFrequência: 2 (duas) vezes por semana<br>\\nValor: R$ 5.148,00<br>\\nVigência: 12 (doze) meses<br>\\nBenefícios do plano:</p>\\n<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>\\n<p>§1º O valor do plano poderá ser pago à vista por PIX ou em até 12 (doze) parcelas fixas mensais no cartão de crédito, lançadas na fatura do cartão do ALUNO, no ato da contratação.</p>\\n<p>§2º Os serviços complementares de nutrição e reabilitação contratados junto com o plano poderão ser incluídos nas mesmas parcelas do cartão de crédito, observada a cláusula 4ª-A.</p>\\n<p>§3º Ao optar pelo pagamento parcelado, o ALUNO autoriza, desde já, a cobrança integral do valor contratado, dividido em parcelas, conforme as condições estabelecidas no momento da compra.</p>\\n<p>§4º É de responsabilidade do ALUNO garantir limite disponível no cartão de crédito para aprovação da transação no ato da contratação.</p>\\n<p>§5º Em caso de não aprovação da transação, o plano não será ativado até a regularização do pagamento por meio válido.</p>\\n<p>§6º Em caso de atraso no pagamento da fatura do cartão de crédito, os encargos (multa, juros e demais acréscimos) serão aplicados diretamente pela administradora do cartão, não sendo de responsabilidade da CONTRATADA.</p>\\n\\n<h2>DOS SERVIÇOS COMPLEMENTARES</h2>\\n<p><strong>Cláusula 4ª-A</strong> – Os serviços complementares de nutrição, reabilitação e avaliação física de composição corporal são contratados à parte, em pacotes, e considerados serviços autônomos e independentes do plano principal:</p>\\n<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>\\n<p>§1º Os créditos dos serviços complementares são liberados no ato da compra e possuem validade de 12 (doze) meses contados da contratação.</p>\\n<p>§2º O cancelamento, a rescisão ou o término do plano principal não afeta os créditos de serviços complementares, que permanecem disponíveis ao ALUNO até o fim do saldo ou da validade, o que ocorrer primeiro.</p>\\n<p>§3º O não comparecimento a atendimento agendado, sem cancelamento prévio conforme as regras internas da CONTRATADA, implicará o consumo do crédito correspondente (No-Show).</p>\\n<p>§4º Os serviços complementares incluídos nas parcelas do plano no cartão de crédito continuam devidos em caso de rescisão do plano, por se tratarem de serviços autônomos, permanecendo exigíveis as respectivas parcelas.</p>\\n\\n<h2>DA RENOVAÇÃO AUTOMÁTICA</h2>\\n<p><strong>Cláusula 5ª</strong> – Ao término do período contratual de 12 (doze) meses, o presente contrato será automaticamente renovado por igual período, garantindo ao ALUNO a continuidade de seus treinos e manutenção de seu vínculo com a CONTRATADA.</p>\\n<p>§1º A CONTRATADA poderá realizar reajustes de valores no momento da renovação, considerando fatores como:</p>\\n<ul>\\n<li>atualização de custos operacionais</li>\\n<li>melhorias na estrutura e serviços</li>\\n<li>inflação do período</li>\\n<li>atualização da política comercial da empresa</li>\\n</ul>\\n<p>§2º A CONTRATADA poderá atualizar a composição de benefícios do plano, podendo incluir, alterar ou descontinuar benefícios, serviços adicionais ou condições promocionais.</p>\\n<p>§3º Eventuais alterações de valores ou benefícios serão comunicadas ao ALUNO com antecedência mínima de 30 (trinta) dias antes do início do novo período contratual.</p>\\n<p>§4º Caso o ALUNO não concorde com as novas condições, poderá manifestar formalmente sua decisão de não renovar o contrato, sem aplicação de multa, até a data anterior ao início do novo período.</p>\\n<p>§5º Na ausência de manifestação dentro do prazo informado, o contrato será considerado automaticamente renovado, passando a vigorar com as condições atualizadas comunicadas pela CONTRATADA.</p>\\n\\n<h2>DO BENEFÍCIO DE RENOVAÇÃO</h2>\\n<p><strong>Cláusula 6ª</strong> – A CONTRATADA poderá conceder benefícios exclusivos para alunos que renovarem seus contratos, tais como:</p>\\n<ul>\\n<li>condições comerciais diferenciadas</li>\\n<li>manutenção de benefícios especiais</li>\\n<li>avaliações adicionais</li>\\n<li>vantagens em serviços complementares</li>\\n</ul>\\n<p>§1º Os benefícios poderão variar conforme campanhas ou políticas internas da CONTRATADA.</p>\\n<p>§2º Os benefícios concedidos possuem caráter promocional e não geram direito adquirido para períodos futuros.</p>\\n\\n<h2>DO AGENDAMENTO DOS TREINOS</h2>\\n<p><strong>Cláusula 7ª</strong> – Os treinos deverão ser previamente agendados pelo ALUNO por meio do aplicativo disponibilizado pela CONTRATADA.</p>\\n<p>§1º O cancelamento ou reagendamento deverá ser realizado com mínimo de 1 (uma) hora de antecedência.</p>\\n<p>§2º O não comparecimento do ALUNO ao treino agendado, sem cancelamento prévio dentro do prazo estabelecido, implicará na perda automática do crédito correspondente à sessão agendada (No-Show).</p>\\n<p>§3º A regra de No-Show visa garantir a adequada organização da agenda e possibilitar a disponibilidade de vagas para outros alunos.</p>\\n<p>§4º Reagendamentos estarão sujeitos à disponibilidade de horários.</p>\\n<p>§5º A sessão de treino terá duração aproximada de até 1 hora e 15 minutos, contados a partir do horário agendado.</p>\\n<p>§6º Em caso de atraso do ALUNO, o treino poderá ser adaptado ao tempo restante da sessão.</p>\\n\\n<h2>DO HORÁRIO DE FUNCIONAMENTO</h2>\\n<p><strong>Cláusula 8ª</strong> – O horário de funcionamento geral da CONTRATADA é:<br>\\nSegundas e Quartas, das 06:00 às 21:00;<br>\\nTerças e Quintas, das 06:00 às 13:00 e das 15:00 às 21:00;<br>\\nSextas-feiras, das 06:00 às 20:00.</p>\\n<p>Parágrafo único – Em caso de feriados nacionais e regionais, a unidade não funcionará.</p>\\n\\n<h2>DAS OBRIGAÇÕES DA CONTRATADA</h2>\\n<p><strong>Cláusula 9ª</strong> – São obrigações da CONTRATADA:</p>\\n<ul>\\n<li>disponibilizar profissionais qualificados para orientação das atividades</li>\\n<li>manter equipamentos e instalações em condições adequadas de uso</li>\\n<li>proporcionar ambiente seguro e organizado para a prática das atividades</li>\\n</ul>\\n\\n<h2>DAS OBRIGAÇÕES DO ALUNO</h2>\\n<p><strong>Cláusula 10ª</strong> – São obrigações do ALUNO:</p>\\n<ul>\\n<li>manter os pagamentos em dia</li>\\n<li>respeitar horários agendados</li>\\n<li>utilizar adequadamente equipamentos e instalações</li>\\n<li>respeitar funcionários e demais alunos</li>\\n<li>cumprir o regulamento interno da CONTRATADA</li>\\n</ul>\\n\\n<h2>DAS SANÇÕES</h2>\\n<p><strong>Cláusula 11ª</strong> – A infração a qualquer das obrigações a que estiver adstrito o ALUNO, nos termos aqui dispostos, importará nas seguintes penalidades, aplicáveis alternativamente:</p>\\n<p>a) advertência com recomendação quanto à alteração de conduta, procedimento ou norma;<br>\\nb) suspensão;<br>\\nc) rescisão do contrato.</p>\\n<p>§1º – Fica estipulado que a CONTRATADA poderá rescindir o presente contrato em casos não previstos neste instrumento, desde que fundamentados na legislação vigente e/ou nos bons costumes.</p>\\n<p>§2º – Em caso de rescisão contratual por culpa do ALUNO, não haverá ressarcimento dos valores pagos.</p>\\n<p>§3º – Os danos causados pelo ALUNO às instalações físicas da CONTRATADA poderão ser cobrados e/ou compensados com créditos remanescentes do plano contratado, ficando a critério da CONTRATADA a escolha da forma de cobrança.</p>\\n\\n<h2>DOS PERTENCES PESSOAIS</h2>\\n<p><strong>Cláusula 12ª</strong> – A CONTRATADA disponibiliza armários para guarda de objetos durante a permanência do ALUNO na unidade.</p>\\n<p>§1º A CONTRATADA não se responsabiliza por objetos deixados fora dos locais destinados à guarda.</p>\\n<p>§2º Objetos esquecidos poderão ser guardados por até 7 dias, após tentativa de contato com o proprietário.</p>\\n<p>§3º Após esse prazo, os objetos poderão ser destinados à doação.</p>\\n\\n<h2>DO CANCELAMENTO E RESCISÃO</h2>\\n<p><strong>Cláusula 13ª</strong> – O ALUNO poderá solicitar o cancelamento do presente contrato a qualquer momento, mediante comunicação formal pelos canais oficiais da CONTRATADA.</p>\\n<p>§1º Considerando que o valor do plano possui condição especial em razão da fidelidade contratual, a rescisão antecipada implicará aplicação de multa compensatória proporcional ao período restante do contrato, conforme critérios abaixo:</p>\\n<p>O ALUNO terá direito à restituição dos valores correspondentes ao período não utilizado, observadas as seguintes deduções:<br>\\naté o 4º mês de contrato: restituição de 75% do valor proporcional restante<br>\\nentre o 5º e 6º mês: restituição de 80% do valor proporcional restante<br>\\nentre o 7º e 12º mês: restituição de 85% do valor proporcional restante</p>\\n<p>§2º Nos pagamentos realizados por cartão de crédito, o estorno será solicitado junto à administradora do cartão, observadas as regras e prazos da respectiva operadora. Caso não seja possível a realização do estorno integral por meio da administradora, a restituição dos valores será efetuada diretamente ao ALUNO, por meio de transferência bancária, podendo ocorrer à vista ou de forma parcelada, conforme os valores efetivamente recebidos pela CONTRATADA, a seu exclusivo critério.</p>\\n<p>§3º Os serviços complementares seguem a cláusula 4ª-A: não integram o cálculo de restituição deste plano, seus créditos não são afetados pela rescisão e as parcelas correspondentes aos serviços incluídos no parcelamento continuam devidas.</p>\\n\\n<h2>DA TRANSFERÊNCIA DO PLANO</h2>\\n<p><strong>Cláusula 14ª</strong> – O ALUNO poderá transferir o período remanescente do plano a terceiro.</p>\\n<p>§1º O terceiro deverá firmar novo contrato com a CONTRATADA.</p>\\n<p>§2º Eventuais diferenças de valores poderão ser ajustadas no momento da transferência.</p>\\n\\n<h2>DO UPGRADE E DOWNGRADE DE PLANO</h2>\\n<p><strong>Cláusula 15ª</strong> – O plano contratado pelo ALUNO possui quantidade total de créditos de treino previamente definida para a vigência contratual de 12 (doze) meses, conforme a frequência semanal escolhida, estando tais créditos disponíveis para utilização ao longo de todo o período contratual.</p>\\n<p>§1º – Downgrade de frequência semanal: Não será permitida a redução da frequência semanal originalmente contratada durante a vigência deste contrato, considerando que a totalidade dos créditos permanece disponível ao ALUNO durante todo o período contratual, permitindo sua utilização de forma distribuída conforme disponibilidade de agenda.</p>\\n<p>§2º – Upgrade de frequência semanal: Será permitida a solicitação de aumento da frequência semanal durante a vigência contratual, hipótese em que:<br>\\nI – será realizado cálculo proporcional dos créditos adicionais necessários à adequação ao novo plano;<br>\\nII – serão considerados os créditos já utilizados e o período restante da vigência contratual;<br>\\nIII – eventuais diferenças financeiras decorrentes do upgrade deverão ser quitadas previamente à ativação da nova frequência.</p>\\n<p>§3º – Créditos de treino, liberados de uma única vez no ato da contratação, para utilização durante toda a vigência de 12 (doze) meses:<br>\\n1 (uma) vez por semana: 52 créditos<br>\\n2 (duas) vezes por semana: 104 créditos<br>\\n3 (três) vezes por semana: 156 créditos<br>\\nplano livre: acesso ilimitado</p>\\n<p>§4º – Upgrade entre categorias de plano (Start, Power e Pro): A migração para categoria superior implicará formalização de novo contrato, ocasião em que:<br>\\nI – os créditos de serviços complementares permanecem válidos, nos termos da cláusula 4ª-A;<br>\\nII – os valores de serviços complementares ainda não integralmente quitados permanecerão exigíveis;<br>\\nIII – eventual diferença financeira deverá ser regularizada previamente à ativação do novo plano.</p>\\n<p>§5º – Cancelamento com finalidade de adesão a plano inferior: Na hipótese de solicitação de cancelamento contratual seguida de nova contratação com frequência semanal inferior ou categoria inferior antes do término da vigência originalmente pactuada, permanecerão aplicáveis:<br>\\nI – a multa de rescisão antecipada prevista neste contrato;<br>\\nII – a exigibilidade dos valores relativos aos serviços complementares contratados;<br>\\nIII – a possibilidade de restrição de concessão de condições promocionais anteriormente praticadas.</p>\\n<p>§6º – Nova contratação durante vigência original: Caso o ALUNO solicite nova contratação antes do término do período originalmente pactuado neste instrumento, a CONTRATADA poderá, observados os princípios da razoabilidade e transparência:<br>\\nI – condicionar a nova contratação à quitação das obrigações financeiras remanescentes;<br>\\nII – limitar a concessão de benefícios promocionais anteriormente aplicados;<br>\\nIII – ajustar a nova contratação conforme a política comercial vigente no momento da solicitação.</p>\\n<p>§7º – Transparência contratual: O ALUNO declara ciência prévia de que os planos são estruturados com base em créditos anuais de treino e benefícios adicionais vinculados à fidelidade contratual, reconhecendo que eventuais alterações de plano durante a vigência dependem de ajuste proporcional entre créditos utilizados, período restante e condições comerciais aplicáveis.</p>\\n<p>§8º – Formalização obrigatória: Qualquer alteração de plano somente produzirá efeitos após formalização expressa entre as partes e eventual regularização financeira correspondente.</p>\\n\\n<h2>DA LICENÇA</h2>\\n<p><strong>Cláusula 16ª</strong> – O ALUNO poderá solicitar licença do plano por até 10 dias corridos, uma única vez durante a vigência contratual.</p>\\n<p>§1º A licença poderá ocorrer em caso de:</p>\\n<ul>\\n<li>viagem</li>\\n<li>doença</li>\\n<li>falta de frequência</li>\\n</ul>\\n<p>§2º O período será acrescido ao final do contrato.</p>\\n<p>§3º Em casos de doença ou lesão comprovada por atestado médico, poderá ser concedida licença de até 30 (trinta) dias, prorrogando igualmente o prazo final do contrato.</p>\\n\\n<h2>DO USO DE IMAGEM</h2>\\n<p><strong>Cláusula 17ª</strong> – A autorização para uso da imagem, voz e nome do ALUNO para fins institucionais, publicitários e promocionais da CONTRATADA será formalizada mediante manifestação expressa no ANEXO I – Declaração de Aptidão Física e Uso de Imagem, no campo específico denominado \\"Direito de Uso de Imagem\\", por meio da devida assinalação de concordância ou não pelo ALUNO.</p>\\n<p>§1º A eventual autorização concedida pelo ALUNO permitirá a utilização gratuita e livre de sua imagem, voz e nome em fotos, vídeos e demais materiais, em meios digitais e físicos, incluindo, mas não se limitando a redes sociais, website, campanhas publicitárias e materiais institucionais.</p>\\n<p>§2º A ausência de autorização expressa, mediante não assinalação ou opção negativa no referido ANEXO I, implicará na vedação do uso da imagem do ALUNO pela CONTRATADA.</p>\\n<p>§3º A autorização concedida poderá ser revogada a qualquer tempo, mediante solicitação formal por escrito pelo ALUNO, produzindo efeitos a partir do seu recebimento pela CONTRATADA, sem efeitos retroativos sobre materiais já publicados ou veiculados.</p>\\n\\n<h2>DAS DISPOSIÇÕES GERAIS</h2>\\n<p><strong>Cláusula 18ª</strong> – O ALUNO declara ter ciência e concordar com o Regulamento Interno da Fortem, que integra o presente contrato.</p>\\n\\n<h2>DO FORO</h2>\\n<p><strong>Cláusula 19ª</strong> – Para todas as questões oriundas do presente pacto, depois de esgotadas as instâncias administrativas e quando não cheguem as partes ao consenso de optar pela mediação, será competente o Foro Central da Comarca de Porto Alegre/RS, com renúncia a qualquer outro, por mais especial que se apresente.</p>\\n\\n<p>As partes declaram, para todos os fins e efeitos de direito, ter previamente lido, entendido e tomado pleno conhecimento do integral conteúdo do presente Contrato, emitido em duas vias de igual teor e forma, diante das duas testemunhas abaixo firmadas e qualificadas, que a tudo presenciaram, bem como que seus dizeres refletem, clara e fielmente, sem qualquer margem a dúvidas, as condições ajustadas, com as quais estão de pleno acordo, obrigando-se a respeitá-las e cumpri-las de forma integral. E por estarem justos e contratados, firmam o presente instrumento.</p>\\n\\n<p>Porto Alegre, 14/10/2026</p>\\n<p>ALUNO<br>\\nACEITE ONLINE<br>\\n<br>\\n<br>\\n<br>\\n<br>\\n</p>\\n<p>Nicolas Squeff Janovik<br>Representante Legal da CONTRATADA</p>\\n<hr/><h1>ANEXO I – DECLARAÇÃO DE APTIDÃO FÍSICA E USO DE IMAGEM</h1>\\n<h2>1. DECLARAÇÃO DE CONDIÇÕES DE SAÚDE</h2>\\n<p>Declaro, para os devidos fins, que: I. Encontro-me em condições físicas e de saúde adequadas para a prática de atividades físicas, incluindo treinos funcionais, exercícios de força e atividades aeróbicas; II. Não possuo, até a presente data, restrições médicas, doenças, lesões ou condições de saúde que impeçam ou limitem a prática de atividades físicas, exceto aquelas que eventualmente tenham sido informadas previamente à equipe da FORTEM; III. Caso possua qualquer condição de saúde relevante, comprometo-me a apresentar atestado ou liberação médica antes do início ou continuidade das atividades.</p>\\n<h2>2. CIÊNCIA DOS RISCOS</h2>\\n<p>Declaro estar ciente de que a prática de atividades físicas envolve riscos inerentes, incluindo, mas não se limitando a: lesões musculares e articulares; quedas; mal-estar físico; fadiga; eventos decorrentes de esforço físico. E que tais riscos podem ocorrer mesmo com acompanhamento profissional adequado.</p>\\n<h2>3. RESPONSABILIDADE E COMPROMISSO</h2>\\n<p>Comprometo-me a: I. Informar imediatamente qualquer alteração no meu estado de saúde; II. Comunicar dores, desconfortos ou limitações durante os treinos; III. Seguir as orientações dos profissionais da FORTEM; IV. Interromper a atividade em caso de sintomas anormais (tontura, dor intensa, falta de ar, etc.).</p>\\n<h2>4. DIREITO DE USO DE IMAGEM</h2>\\n<p>Autorizo, de forma gratuita e livre, a utilização da minha imagem, voz e nome pela FORTEM TREINAMENTO FÍSICO LTDA, para fins de divulgação institucional, publicitária e promocional, em meios digitais e físicos. Declaro estar ciente de que esta autorização pode ser revogada a qualquer momento mediante solicitação formal.</p>\\n<h2>5. ISENÇÃO DE RESPONSABILIDADE</h2>\\n<p>Declaro que a omissão de informações relevantes sobre minha condição de saúde poderá resultar em riscos à minha integridade física, isentando a FORTEM de responsabilidade por eventuais danos decorrentes dessa omissão.</p>\\n<h2>6. AUTORIZAÇÃO EM CASO DE EMERGÊNCIA</h2>\\n<p>Autorizo, em caso de emergência, o acionamento de serviços médicos, estando ciente de que eventuais custos decorrentes serão de minha responsabilidade.</p>\\n<h2>7. VALIDADE</h2>\\n<p>A presente declaração é válida por prazo indeterminado a partir da data de assinatura, devendo ser atualizada em caso de alteração no estado de saúde.</p>\\n<h2>8. DECLARAÇÃO FINAL</h2>\\n<p>Declaro que li, compreendi e concordo integralmente com todos os termos deste documento, assumindo plena responsabilidade pelas informações prestadas.</p>\\n<h2>RESPOSTAS DO ALUNO (ANEXO I ACEITO)</h2>\\n<p>Aluno: Nicolas Squeff Janovik</p>\\n<p>Avaliação Médica: Nenhum médico informou restrições à prática de atividade física (sem restrições)</p>\\n<p>Direito de Uso de Imagem: Autorizo</p>\\n<p>Contato de emergência: Hahaha · (**) *****-9999</p>\\n<p>Política de Privacidade (LGPD): aceita · Termos lidos até o fim: sim · Assinatura eletrônica desenhada registrada</p>\\n<p>Versão do texto: anexo1-2027-v1 · Aceito em 14/10/2026, 14:11</p>","variaveis":{"RG": "", "UF": "RS", "ANO": "2026", "CEP": "90620-001", "CPF": "***.***.**041", "DIA": "14", "MES": "10", "NOME": "Nicolas Squeff Janovik", "EMAIL": "nicolas.janovik@gmail.com", "BAIRRO": "Santana", "CIDADE": "Porto Alegre", "ENDERECO": "Avenida Princesa Isabel, 1155", "FREQUENCIA": "2 (duas) vezes por semana", "LICENCA_DIAS": "10", "VALOR_MENSAL": "R$ 5.148,00", "NOME_CONTRATO": "Power 2x", "DATA_NASCIMENTO": "02/12/1989", "TABELA_SERVICOS": "<ul>\\n<li>Nutrição - 8 consultas: R$ 2.400,00</li>\\n<li>Nutrição - 4 consultas + 2 Avaliações de Composição Corporal: R$ 1.620,00</li>\\n<li>Reabilitação - 8 sessões: R$ 1.200,00</li>\\n<li>Reabilitação - 4 sessões: R$ 600,00</li>\\n<li>Avaliação Física de Composição Corporal: R$ 200,00</li>\\n</ul>", "BENEFICIOS_PLANO": "<ul>\\n<li>1 (uma) avaliação funcional no 1º mês</li>\\n<li>10 dias de licença</li>\\n<li>brinde: camiseta</li>\\n</ul>", "TAXA_RECORRENCIA": "R$ 0,00", "CLAUSULA_REPOSICAO": "", "VALOR_FINAL_CONTRATO": "R$ 5.148,00"},"hash_texto":"faa38f2345e74710553a60c07bbcb43d5f37adf60162942bb5a44b4bf46d01f4","valor_total_centavos":514800,"ip":"189.6.254.50","user_agent":"Mozilla/5.0 (iPhone; CPU iPhone OS 18_7 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15E148 LovableApp/1.2.3 LovableAppScheme/lovable","origem":"site","aceito_em":"2026-10-14T17:11:30.404782+00:00","invalidado_em":null,"motivo_invalidacao":null,"created_at":"2026-10-14T17:11:30.404782+00:00","anexo":{"lgpd": true, "versao": "anexo1-2027-v1", "image_usage": true, "termos_lidos": true, "medical_status": "ok", "emergency_contact_name": "Hahaha", "emergency_contact_phone": "51999999999"},"anexo_versao":"anexo1-2027-v1","anexo_assinatura":"data:image/png;base64,"}');
